"""
PanelTimer — single-message auto-close timer for inline panels.

Respects the global auto-close preference (panel_settings).
When auto-close is OFF globally, no timer task is created at all.

When ON, a single asyncio task per panel edits the SAME inline message
every 30 seconds with the updated countdown:
  120s → 90s → 60s → 30s → delete

No second message. No new messages. Only edits.
"""
import asyncio
import logging

from backend.helper.panel_settings import is_auto_close_enabled

logger = logging.getLogger(__name__)

_DURATION = 120
_COUNTDOWN_INTERVAL = 30
_COUNTDOWN_VALUES = [90, 60, 30]


class _PanelEntry:
    __slots__ = ("expire_at", "task", "title", "body", "buttons")

    def __init__(self):
        self.expire_at: float = 0.0
        self.task: asyncio.Task | None = None
        self.title: str = "LifeOS"
        self.body: str = ""
        self.buttons: list = []


_panels: dict[str, _PanelEntry] = {}


def _key(chat_id: int, msg_id: int) -> str:
    return f"{chat_id}:{msg_id}"


def _now() -> float:
    return asyncio.get_event_loop().time()


def init_panel(self_client, chat_id: int, msg_id: int, title: str = "LifeOS", body: str = "", buttons: list = None) -> None:
    """Register a panel and start its timer (only if auto-close is globally ON)."""
    k = _key(chat_id, msg_id)
    _cancel_task(k)
    entry = _PanelEntry()
    entry.title = title
    entry.body = body
    entry.buttons = buttons or []
    _panels[k] = entry
    if is_auto_close_enabled():
        _start_timer(self_client, chat_id, msg_id, entry)


def set_content(chat_id: int, msg_id: int, title: str, body: str, buttons: list) -> None:
    """Update stored panel content for countdown re-renders."""
    k = _key(chat_id, msg_id)
    entry = _panels.get(k)
    if entry is None:
        entry = _PanelEntry()
        _panels[k] = entry
    entry.title = title
    entry.body = body
    entry.buttons = buttons or []


def _start_timer(self_client, chat_id: int, msg_id: int, entry: _PanelEntry) -> None:
    entry.expire_at = _now() + _DURATION
    entry.task = asyncio.create_task(_timer_loop(self_client, chat_id, msg_id))


def _cancel_entry_task(entry: _PanelEntry) -> None:
    if entry.task and not entry.task.done():
        entry.task.cancel()
    entry.task = None


def _cancel_task(k: str) -> None:
    entry = _panels.get(k)
    if entry:
        _cancel_entry_task(entry)


async def _timer_loop(self_client, chat_id: int, msg_id: int) -> None:
    """Single task: countdown every 30s via edits, then delete at 120s."""
    try:
        for value in _COUNTDOWN_VALUES:
            await asyncio.sleep(_COUNTDOWN_INTERVAL)
            entry = _panels.get(_key(chat_id, msg_id))
            if entry is None or entry.task is None or entry.task.done():
                return
            if not is_auto_close_enabled():
                return
            await _edit_countdown(self_client, chat_id, msg_id, value)
        await asyncio.sleep(_COUNTDOWN_INTERVAL)
        entry = _panels.get(_key(chat_id, msg_id))
        if entry is None or not is_auto_close_enabled():
            return
        destroy(self_client, chat_id, msg_id)
    except asyncio.CancelledError:
        raise
    except Exception:
        pass


async def _edit_countdown(self_client, chat_id: int, msg_id: int, seconds: int) -> None:
    """Edit the inline message with the updated countdown value."""
    k = _key(chat_id, msg_id)
    entry = _panels.get(k)
    if entry is None:
        return
    header = f"**{entry.title}**\n\n⏱ {seconds}s"
    if entry.body:
        full_text = f"{header}\n\n{entry.body}"
    else:
        full_text = header
    try:
        await self_client.edit_message(chat_id, msg_id, message=full_text)
    except Exception:
        pass


def destroy(self_client, chat_id: int, msg_id: int) -> None:
    """Fully clear timer state and delete the panel message."""
    k = _key(chat_id, msg_id)
    entry = _panels.pop(k, None)
    if entry:
        _cancel_entry_task(entry)
    try:
        asyncio.create_task(self_client.delete_messages(chat_id, [msg_id]))
    except Exception:
        pass


def stop_timer(chat_id: int, msg_id: int) -> None:
    """Cancel timer without deleting the message."""
    k = _key(chat_id, msg_id)
    entry = _panels.pop(k, None)
    if entry:
        _cancel_entry_task(entry)


def has_timer(chat_id: int, msg_id: int) -> bool:
    k = _key(chat_id, msg_id)
    entry = _panels.get(k)
    return entry is not None and entry.task is not None and not entry.task.done()


def active_count() -> int:
    return sum(1 for e in _panels.values() if e.task is not None and not e.task.done())

"""
TargetContext — abstracts how a panel resolves its target message.

Supports:
  - Reply target (a message the owner replied to)
  - Future Link target (reserved for future link-based targeting)
  - Future Forward target (reserved for future forward-based targeting)

The panel system never knows how the target was resolved — it only
requests a TargetContext and calls resolve() to get the message object.
"""
import logging
import time
from dataclasses import dataclass, field
from typing import Any

logger = logging.getLogger(__name__)

_EXPIRY_S = 300
_store: dict[int, "TargetContext"] = {}


@dataclass
class TargetContext:
    owner_id: int
    kind: str
    reply_chat_id: int = 0
    reply_msg_id: int = 0
    tz_str: str = "UTC"
    _ts: float = field(default_factory=time.time)

    def is_expired(self) -> bool:
        return time.time() - self._ts > _EXPIRY_S

    async def resolve(self, client: Any):
        if self.kind != "reply":
            return None
        if not self.reply_chat_id or not self.reply_msg_id:
            return None
        try:
            return await client.get_messages(self.reply_chat_id, ids=self.reply_msg_id)
        except Exception as exc:
            logger.warning("TargetContext resolve failed: %s", exc)
            return None


def set_target(owner_id: int, ctx: TargetContext) -> None:
    _store[owner_id] = ctx


def get_target(owner_id: int) -> TargetContext | None:
    ctx = _store.get(owner_id)
    if ctx is None:
        return None
    if ctx.is_expired():
        _store.pop(owner_id, None)
        return None
    return ctx


def clear_target(owner_id: int) -> TargetContext | None:
    return _store.pop(owner_id, None)

"""
Database service — all database maintenance business logic lives here.

Both text commands and inline panels call these exact functions.
"""
import asyncio
import logging
from datetime import datetime

from backend.db import client as db_client
from backend.bio.engine import _get_tz
from backend.diagnostics import record_event

logger = logging.getLogger(__name__)

_MEDIA_ICON = {
    "Photo": "📷",
    "Video": "🎬",
    "Animation": "🎞",
    "Audio": "🎵",
    "Voice": "🎤",
    "Sticker": "🏷",
    "Document": "📄",
    "Unknown": "📦",
}


def icon(media_type: str | None) -> str:
    return _MEDIA_ICON.get(media_type or "Unknown", "📦")


def format_date(iso_str: str | None, tz_str: str) -> str:
    if not iso_str:
        return "—"
    try:
        dt = datetime.fromisoformat(iso_str.replace("Z", "+00:00"))
        return dt.strftime("%d %b %Y")
    except Exception:
        return str(iso_str)[:10]


async def find_orphans(client, owner_id: int) -> tuple[list[int], int]:
    items = db_client.list_all_saves(owner_id)
    orphan_ids: list[int] = []
    for item in items:
        saved_chat_id = item.get("saved_chat_id")
        saved_msg_id = item.get("saved_msg_id")
        if not saved_chat_id or not saved_msg_id:
            orphan_ids.append(item.get("id"))
            continue
        try:
            msg = await client.get_messages(saved_chat_id, ids=saved_msg_id)
            if msg is None or (isinstance(msg, list) and not any(m is not None for m in msg)):
                orphan_ids.append(item.get("id"))
        except Exception:
            pass
    return orphan_ids, len(items)


async def do_clean(client, owner_id: int) -> str:
    t0 = asyncio.get_event_loop().time()
    try:
        orphan_ids, total = await find_orphans(client, owner_id)
        removed = db_client.cleanup_orphans(owner_id, orphan_ids)
        remaining = total - removed
        record_event("database", "clean orphans", (asyncio.get_event_loop().time() - t0) * 1000, "SUCCESS", f"{removed}/{total}")
        await db_client.log(owner_id, "INFO", f"DB clean: removed {removed} orphans", {
            "removed": removed, "remaining": remaining,
        })
        return (
            f"🧹 **Database cleanup complete**\n\n"
            f"Removed: `{removed}` orphan rows\n"
            f"Remaining: `{remaining}` items"
        )
    except Exception as exc:
        logger.error("db clean failed: %s", exc)
        record_event("database", "clean orphans", 0, "ERROR", str(exc))
        await db_client.log(owner_id, "ERROR", f"DB clean failed: {exc}", {})
        return f"❌ Cleanup error: {exc}"


async def do_stats(owner_id: int, tz_str: str) -> str:
    t0 = asyncio.get_event_loop().time()
    try:
        stats = db_client.get_stats(owner_id)
        total = stats["total"]
        by_type = stats["by_type"]
        size_bytes = stats["size_estimate"]

        if size_bytes >= 1024 * 1024:
            size_str = f"{size_bytes / (1024 * 1024):.1f} MB"
        elif size_bytes >= 1024:
            size_str = f"{size_bytes / 1024:.1f} KB"
        else:
            size_str = f"{size_bytes} B"

        lines = [
            f"📊 **Database Statistics**\n",
            f"Total saved items: `{total}`\n",
            f"**Breakdown by type:**",
        ]
        for mt in ["Photo", "Video", "Animation", "Audio", "Voice", "Document", "Unknown"]:
            count = by_type.get(mt, 0)
            if count:
                lines.append(f"  {icon(mt)} {mt}: `{count}`")

        lines.append(f"\n**Database size estimate:** `{size_str}`")
        lines.append(f"**Oldest save:** {format_date(stats['oldest'], tz_str)}")
        lines.append(f"**Newest save:** {format_date(stats['newest'], tz_str)}")

        await db_client.log(owner_id, "INFO", f"DB stats: {total} items", stats)
        record_event("database", "stats", (asyncio.get_event_loop().time() - t0) * 1000, "SUCCESS")
        return "\n".join(lines)
    except Exception as exc:
        logger.error("db stats failed: %s", exc)
        record_event("database", "stats", 0, "ERROR", str(exc))
        return f"❌ Stats error: {exc}"


async def do_vacuum(client, owner_id: int) -> str:
    t0 = asyncio.get_event_loop().time()
    try:
        orphan_ids, total = await find_orphans(client, owner_id)
        removed = db_client.cleanup_orphans(owner_id, orphan_ids)
        remaining = total - removed
        record_event("database", "vacuum", (asyncio.get_event_loop().time() - t0) * 1000, "SUCCESS", f"{removed}/{total}")
        await db_client.log(owner_id, "INFO", f"DB vacuum: removed {removed} orphans", {
            "removed": removed, "remaining": remaining,
        })
        return (
            f"⚙️ **Vacuum complete**\n\n"
            f"Orphans removed: `{removed}`\n"
            f"Items remaining: `{remaining}`\n"
            f"Index optimization: skipped (PostgREST)"
        )
    except Exception as exc:
        logger.error("db vacuum failed: %s", exc)
        record_event("database", "vacuum", 0, "ERROR", str(exc))
        await db_client.log(owner_id, "ERROR", f"DB vacuum failed: {exc}", {})
        return f"❌ Vacuum error: {exc}"
